  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv: Ajv = new AjvModule.default({strict: false, validateFormats: false});

function compileSchema(ajv: Ajv, tool: ToolDefinition): ValidateFunction {
  try {
    return ajv.compile(tool.inputSchema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${tool.name}": ${String(error)}`, {cause: error});
  }
}

