import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger();
  });

  it('throws at register time when a static inputSchema is invalid and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {city: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'ok'
      )
    ).toThrow(/broken_tool/);
  });

  it('returns a ToolResponse naming the field and expected type without echoing or logging the rejected value', async () => {
    const emitted: string[] = [];
    const capture = (category: string, message: string, fields?: Record<string, unknown>) => {
      emitted.push(`${category}:${message}:${JSON.stringify(fields)}`);
    };
    setLogger({debug: capture, info: capture, warn: capture, error: capture});
    const registry = new ToolRegistry();
    let invocations = 0;
    registry.register(
      {
        name: 'lookup_patient',
        description: 'Finds a patient record',
        inputSchema: {
          type: 'object',
          required: ['patientId'],
          properties: {patientId: {type: 'string'}},
        },
      },
      async () => {
        invocations += 1;
        return 'record';
      }
    );

    const outcome = await registry.execute('lookup_patient', {patientId: 987654321});

    expect({
      invocations,
      resultNamesFieldAndType: /patientId.*string/.test(outcome.result),
      logNamesFieldAndType: emitted.some(entry => /patientId.*string/.test(entry)),
      valueAppearsInOutput: [outcome.result, ...emitted].some(text => text.includes('987654321')),
    }).toEqual({
      invocations: 0,
      resultNamesFieldAndType: true,
      logNamesFieldAndType: true,
      valueAppearsInOutput: false,
    });
  });
});

