/** Validates input per specs/hal-engine-tool-input-validation/spec.md before invoking the executor. */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }
  const {validator} = tool;
  if (validator && !validator(input)) {
    const failure = this.ajv.errorsText(validator.errors, {dataVar: 'input'});
    log.warn('tool', 'input validation failed', {name, failure});
    return {result: `Invalid input for tool "${name}": ${failure}`};
  }
  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});

